
const QUESTIONS=[{"cat":"Licensing","q":"How old must you be to apply for an Alberta Class 7 learner's licence?","a":["14","15","16","18"],"correct":0,"why":"You must be at least 14 years old."},{"cat":"Licensing","q":"What must a new Class 7 applicant under 18 have?","a":["A school letter","Parental or guardian consent","A vehicle","A driving-school certificate"],"correct":1,"why":"A parent or legal guardian must provide consent."},{"cat":"Licensing","q":"Which tests are required to obtain a Class 7 learner's licence?","a":["Road and hearing tests","Vision and knowledge tests","Medical and road tests","Knowledge test only"],"correct":1,"why":"A Class 7 applicant must pass a vision screening and the knowledge test."},{"cat":"Licensing","q":"How long must you hold a Class 7 licence before becoming eligible for Class 5-GDL?","a":["6 months","9 months","At least 1 year","2 years"],"correct":2,"why":"The minimum learner stage is one year."},{"cat":"Licensing","q":"Who may supervise a Class 7 driver?","a":["Any driver over 18","A fully licensed non-GDL driver age 18 or older seated beside the learner","Any Class 5-GDL driver","A parent only"],"correct":1,"why":"The supervisor must be fully licensed, non-GDL, at least 18, and seated next to the learner."},{"cat":"Licensing","q":"When is a Class 7 learner prohibited from driving?","a":["10 p.m. to 6 a.m.","11 p.m. to 5 a.m.","Midnight to 5 a.m.","There is no time restriction"],"correct":2,"why":"Class 7 learners may not drive between midnight and 5 a.m."},{"cat":"Licensing","q":"At how many demerit points is a Class 7 learner suspended?","a":["6 or more","8 or more","12 or more","15 or more"],"correct":1,"why":"Learners are suspended at eight or more demerit points."},{"cat":"Licensing","q":"What alcohol or drug level must a Class 7 driver have while driving?","a":["Below 0.05","Below 0.08","Zero","Any amount if supervised"],"correct":2,"why":"Class 7 drivers must have zero alcohol and drug levels when driving."},{"cat":"Licensing","q":"How old must a learner be to qualify for Class 5-GDL?","a":["15","16","17","18"],"correct":1,"why":"The minimum age for Class 5-GDL is 16, after holding Class 7 for at least one year and passing the road test."},{"cat":"Licensing","q":"How many knowledge tests may a person take in one day?","a":["One","Two","Three","Unlimited"],"correct":0,"why":"The guide states that only one knowledge test may be taken per day."},{"cat":"Signals","q":"At a solid red light, where must you stop?","a":["Past the crosswalk","Before the stop line or crosswalk","In the intersection","Beside the signal pole"],"correct":1,"why":"Stop before the stop line or crosswalk; if neither exists, stop before the intersection."},{"cat":"Signals","q":"May you turn right at a red light in Alberta?","a":["Never","Only from a one-way street","Yes, after a complete stop if no sign prohibits it and the way is safe","Only when another driver waves you through"],"correct":2,"why":"Right on red is permitted after stopping, unless prohibited, while yielding to other traffic and pedestrians."},{"cat":"Signals","q":"When may you turn left at a red light?","a":["From any street onto a one-way street","Only from a one-way street onto a one-way street, after stopping and yielding","From a two-way street onto a one-way street","Never"],"correct":1,"why":"The only left turn permitted on red is from a one-way street onto a one-way street, unless prohibited."},{"cat":"Signals","q":"A solid yellow light means:","a":["Speed up before red","Stop if it can be done safely; otherwise clear the intersection","Always stop immediately","Proceed without caution"],"correct":1,"why":"Yellow warns that red is immediate. Stop unless you have reached a point where stopping cannot be done safely."},{"cat":"Signals","q":"A flashing red light is treated like:","a":["A yield sign","A stop sign","A green light","A school-zone sign"],"correct":1,"why":"Stop completely, then proceed only when safe after yielding."},{"cat":"Signals","q":"A flashing yellow light means:","a":["Stop completely","Proceed with caution after yielding as necessary","The road is closed","Speed up"],"correct":1,"why":"Proceed cautiously and yield to pedestrians and vehicles within the intersection."},{"cat":"Signals","q":"What does a red X above a lane mean?","a":["Lane is for buses","Lane is closed to you or being used by oncoming traffic","Passing is permitted","Lane ends soon"],"correct":1,"why":"Do not enter or remain in a lane displaying a red X."},{"cat":"Signals","q":"What does a downward green arrow above a lane mean?","a":["You may travel in that lane","The lane is closing","Turn only","Stop under the arrow"],"correct":0,"why":"A downward green arrow permits travel in that lane."},{"cat":"Signs & Speed","q":"What does a red circle and slash over a symbol mean?","a":["The action is required","The action is recommended","The action is not permitted","The action is permitted at night"],"correct":2,"why":"A red circle and slash means the pictured action is prohibited."},{"cat":"Signs & Speed","q":"What does a green circle on a white sign indicate?","a":["The action is permitted","The action is prohibited","Construction ahead","A warning"],"correct":0,"why":"A green circle indicates a permitted action."},{"cat":"Signs & Speed","q":"What shape is commonly used for a warning sign?","a":["Octagon","Diamond","Pentagon","Circle"],"correct":1,"why":"Warning signs are generally yellow diamonds."},{"cat":"Signs & Speed","q":"What colour is typically used for construction-area signs?","a":["Blue","Orange","Green","White"],"correct":1,"why":"Construction information is generally shown on orange diamond-shaped signs."},{"cat":"Signs & Speed","q":"Unless otherwise posted, what is the maximum speed on an urban roadway?","a":["40 km/h","50 km/h","60 km/h","80 km/h"],"correct":1,"why":"The general maximum is 50 km/h in an urban area, though municipalities may set different limits."},{"cat":"Signs & Speed","q":"Unless otherwise posted, what is the maximum speed on a provincial highway outside an urban area?","a":["80 km/h","90 km/h","100 km/h","110 km/h"],"correct":2,"why":"The guide gives 100 km/h as the general maximum on a provincial highway outside an urban area."},{"cat":"Signs & Speed","q":"A posted speed limit is:","a":["The speed you must always drive","The maximum permitted only when conditions are ideal","A minimum speed","Optional when traffic is light"],"correct":1,"why":"A speed can still be illegal if it is unsafe for current conditions, even below the posted maximum."},{"cat":"Signs & Speed","q":"A stop sign requires you to:","a":["Slow and roll through if clear","Come to a complete stop and proceed only when safe","Stop only if traffic is present","Yield without stopping"],"correct":1,"why":"A stop sign requires a full stop."},{"cat":"Signs & Speed","q":"At a yield sign, you must yield to:","a":["Traffic not facing the sign and pedestrians","Only vehicles on your left","Only large vehicles","Nobody if you arrived first"],"correct":0,"why":"Yield to traffic not facing the sign and to pedestrians waiting to cross or already within the crossing."},{"cat":"Zones","q":"When flashing yellow lights at a pedestrian crossing are active, what maximum speed applies?","a":["20 km/h","30 km/h","40 km/h","50 km/h"],"correct":1,"why":"Reduce speed to a maximum of 30 km/h and yield or stop for pedestrians."},{"cat":"Zones","q":"A school-zone sign is generally what shape?","a":["Pentagon","Octagon","Triangle","Circle"],"correct":0,"why":"School zone/area signs use a fluorescent yellow-green pentagon."},{"cat":"Driving Basics","q":"Before moving a vehicle, what should you do first?","a":["Turn on music","Adjust seat, mirrors and restraints and check surroundings","Release the park brake immediately","Accelerate to test the engine"],"correct":1,"why":"Pre-drive preparation includes seating, mirrors, restraints, controls and a check around the vehicle."},{"cat":"Driving Basics","q":"When signalling a turn, the signal should be given:","a":["Only after beginning the turn","Early enough to warn other road users","Only when traffic is heavy","Only at traffic lights"],"correct":1,"why":"Signals communicate your intentions and must be given with enough time for others to respond."},{"cat":"Driving Basics","q":"When reversing, you should primarily look:","a":["Only at the backup camera","Through the rear window in the direction of travel while checking all around","Only in the left mirror","At the dashboard"],"correct":1,"why":"Cameras and mirrors assist, but they do not replace looking in the direction the vehicle is moving and checking around it."},{"cat":"Driving Basics","q":"Why does stopping distance increase at higher speeds?","a":["Only because brakes get hotter","Both reaction distance and braking distance increase","It does not increase","Tires become larger"],"correct":1,"why":"The vehicle travels farther while the driver reacts and takes farther to brake as speed rises."},{"cat":"Intersections","q":"At an uncontrolled intersection, you should be prepared to yield to:","a":["The driver on your right","The driver on your left","The largest vehicle","The fastest vehicle"],"correct":0,"why":"At an uncontrolled intersection, yield to the vehicle on your right when arrivals conflict."},{"cat":"Intersections","q":"Can you enter an intersection if traffic is backed up and you cannot clear it?","a":["Yes, if the light is green","No, keep the intersection clear","Yes, if you honk","Only during rush hour"],"correct":1,"why":"Do not enter unless you can clear the intersection."},{"cat":"Intersections","q":"When turning left, you normally must yield to:","a":["Oncoming traffic and pedestrians","Vehicles behind you only","Nobody when the light is green","Only cyclists"],"correct":0,"why":"A solid green permits movement, but left-turning drivers must yield to oncoming traffic and pedestrians."},{"cat":"Intersections","q":"When entering a roundabout, you must yield to:","a":["Vehicles entering behind you","Traffic already in the roundabout","Only vehicles on your right outside it","Nobody"],"correct":1,"why":"Traffic already circulating has priority."},{"cat":"Intersections","q":"In a multi-lane turn, what should you do during and after the turn?","a":["Change lanes during the turn","Maintain your lane position","Move to the widest lane","Follow the car beside you"],"correct":1,"why":"Maintain the lane indicated for your turn throughout the turn."},{"cat":"Intersections","q":"At a four-way stop, if two vehicles arrive at the same time, which normally goes first?","a":["The vehicle on the left","The vehicle on the right","The larger vehicle","The vehicle going faster"],"correct":1,"why":"When arrival is simultaneous, the vehicle on the right normally proceeds first."},{"cat":"Highways","q":"Before changing lanes, what sequence is safest?","a":["Signal, mirror, shoulder check, move when safe","Move, then signal","Honk, then move","Check only the rear-view mirror"],"correct":0,"why":"Signal your intention, check mirrors and blind spot, then move only when there is a safe gap."},{"cat":"Highways","q":"When entering a freeway, you should generally:","a":["Stop at the end of the acceleration lane","Use the acceleration lane to match traffic speed and merge into a safe gap","Enter at a very low speed","Force traffic to yield"],"correct":1,"why":"Use the acceleration lane to build an appropriate speed and merge safely; freeway traffic has priority."},{"cat":"Highways","q":"On a two-lane highway, passing should be attempted only when:","a":["You are impatient","It is legal and there is enough clear distance to complete it safely","The vehicle ahead is at the speed limit","You can exceed the speed limit"],"correct":1,"why":"Passing is high-risk and must be both legal and safely completed within clear sight distance."},{"cat":"Highways","q":"May you exceed the speed limit while passing?","a":["Yes, by 10 km/h","Yes, briefly","No","Only on rural roads"],"correct":2,"why":"The speed limit continues to apply while passing."},{"cat":"Hazards","q":"If your vehicle begins to skid, where should you look?","a":["At the hazard","In the direction you want the vehicle to go","At the dashboard","At the shoulder"],"correct":1,"why":"Look and steer toward your intended path while making smooth corrections."},{"cat":"Hazards","q":"In poor visibility or slippery conditions, you should:","a":["Drive at the posted maximum","Reduce speed and increase following distance","Follow closely so you can see the vehicle ahead","Use cruise control"],"correct":1,"why":"Conditions may require a speed well below the posted limit and more space to stop."},{"cat":"Hazards","q":"If a tire blows out, you should generally:","a":["Brake hard immediately","Hold the steering wheel firmly, ease off the accelerator and slow gradually","Turn sharply to the shoulder","Accelerate"],"correct":1,"why":"Maintain control and reduce speed gradually before moving off the road when safe."},{"cat":"Hazards","q":"When approaching an emergency vehicle stopped with lights flashing, you should:","a":["Maintain speed","Slow down and move over when safe as required","Stop in your lane","Pass closely"],"correct":1,"why":"Protect roadside workers and responders by slowing and moving over safely."},{"cat":"Responsible Driving","q":"What is proactive driving?","a":["Driving aggressively to make progress","Continuously observing, anticipating hazards and taking action before problems develop","Driving only in daylight","Following the vehicle ahead closely"],"correct":1,"why":"Proactive driving aims to prevent collisions through continuous observation and anticipation."},{"cat":"Responsible Driving","q":"How many passengers may a Class 7 or Class 5-GDL driver carry?","a":["Any number","No more than the number of seat belts","One passenger only","Two passengers only"],"correct":1,"why":"There may not be more passengers than available seat belts."},{"cat":"Sharing the Road","q":"When a school bus has alternating red lights flashing, drivers must:","a":["Pass slowly","Stop as required and do not pass until the lights stop flashing","Honk before passing","Stop only behind the bus"],"correct":1,"why":"Flashing red school-bus lights require traffic to stop as prescribed; passing is dangerous and unlawful."},{"cat":"Sharing the Road","q":"At a railway crossing, you should never:","a":["Look both ways","Stop on the tracks","Reduce distractions","Obey signals"],"correct":1,"why":"Never enter unless you can completely clear the tracks."},{"cat":"Sharing the Road","q":"Why should you give cyclists extra space?","a":["They always have right-of-way","They are vulnerable and may need room to avoid hazards","They cannot use roads","They travel faster than cars"],"correct":1,"why":"Cyclists are vulnerable road users and may need lateral space to deal with debris, doors and road conditions."},{"cat":"Sharing the Road","q":"When following a large truck, why should you leave extra space?","a":["To see around it and stay out of its blind spots","Because trucks always stop faster","So another car can cut in","To use less fuel only"],"correct":0,"why":"Large vehicles limit your view and have large blind spots; extra space improves visibility and safety."},{"cat":"Law & Fitness","q":"What documents must a driver be able to produce when requested by a peace officer?","a":["Licence only","Licence, insurance and registration","Passport and birth certificate","Road-test permit only"],"correct":1,"why":"The driver must carry and produce a valid licence, insurance and registration."},{"cat":"Law & Fitness","q":"Is it legal to operate an uninsured motor vehicle?","a":["Yes, for short trips","Yes, with a learner","No","Only during daytime"],"correct":2,"why":"All motor vehicles must carry the required public-liability insurance."},{"cat":"Law & Fitness","q":"What should a driver do about a medical condition that may affect safe driving?","a":["Keep it private","Disclose it as required and provide medical documentation","Drive only with a friend","Wait until a collision occurs"],"correct":1,"why":"The guide requires disclosure of medical or physical conditions that could affect safe operation."},{"cat":"Scenarios","q":"The light is green, but cars are stopped across the intersection. What should Andy do?","a":["Enter and wait in the intersection","Stay back until there is room to clear it","Honk until they move","Drive around them"],"correct":1,"why":"A green light does not permit blocking the intersection."},{"cat":"Scenarios","q":"Andy reaches a yellow light and can stop smoothly before the line. What should he do?","a":["Accelerate","Stop","Swerve around traffic","Continue because yellow means go"],"correct":1,"why":"A driver must stop for a solid yellow when stopping can be done safely."},{"cat":"Scenarios","q":"Andy is driving below the posted limit during heavy rain. Is that automatically safe and legal?","a":["Yes","No; he must choose a speed safe for conditions","Yes, if hazards are on","Only on highways"],"correct":1,"why":"Even a speed below the limit can be unsafe for current conditions."},{"cat":"Scenarios","q":"A pedestrian is crossing the street Andy wants to turn into. What must he do?","a":["Turn before the pedestrian reaches his lane","Yield and wait until the turn is safe","Honk to warn them","Drive behind them within the crosswalk"],"correct":1,"why":"Turning drivers must yield to pedestrians in the crossing."},{"cat":"Scenarios","q":"At an uncontrolled intersection, another vehicle approaches from Andy's right at the same time. What should Andy do?","a":["Speed through","Yield to the vehicle on the right","Wave them to stop","Use the horn and proceed"],"correct":1,"why":"The driver on the left yields to the driver on the right when arrival conflicts."},{"cat":"Driving Basics","q":"Before moving a vehicle, what should you adjust first?","a":["Only the radio","Seat, head restraint and mirrors","The climate control","The odometer"],"correct":1,"why":"Adjust the seat, head restraint and mirrors so you can control the vehicle and see properly before moving."},{"cat":"Driving Basics","q":"When reversing, where should you primarily look?","a":["Only at the backup camera","In the direction the vehicle is moving, with frequent checks around the vehicle","Only in the rear-view mirror","At the front wheels"],"correct":1,"why":"Look mainly through the rear window in the direction of travel and continue checking all around. Cameras and mirrors are aids, not substitutes."},{"cat":"Driving Basics","q":"Why should you check behind the vehicle before getting in to reverse?","a":["To warm up the tires","Small children or objects may be hidden from the driver's seat","To inspect the licence plate","It is required only on a road test"],"correct":1,"why":"The area immediately behind a vehicle may not be visible from the driver's seat."},{"cat":"Responsible Driving","q":"What following distance should normally be maintained in ideal conditions?","a":["At least 1 second","At least 2 seconds","At least 4 seconds","Exactly 10 metres"],"correct":1,"why":"The guide recommends at least a two-second following distance in ideal conditions, increased when conditions are poor."},{"cat":"Responsible Driving","q":"When conditions are poor, what should happen to your following distance?","a":["It should be reduced","It should stay exactly the same","It should be increased","It matters only at night"],"correct":2,"why":"Increase following distance when visibility, traction or stopping ability is reduced."},{"cat":"Hazards","q":"When following another vehicle within 150 metres at night, which headlights should you use?","a":["High beams","Low beams","Parking lights only","Hazard lights"],"correct":1,"why":"Use low-beam headlights when following another vehicle within 150 metres."},{"cat":"Hazards","q":"When within 300 metres of an oncoming vehicle at night, which headlights should you use?","a":["High beams","Low beams","Daytime running lights only","Hazard lights"],"correct":1,"why":"Use low beams when you are within 300 metres of an oncoming vehicle."},{"cat":"Hazards","q":"Why should high beams not be used in fog or heavy smoke?","a":["They use too much fuel","The light reflects back and reduces visibility","They are illegal at all times","They make the road slippery"],"correct":1,"why":"High beams reflect off fog, smoke or snow and can make it harder to see. Use low beams."},{"cat":"Sharing the Road","q":"On an undivided roadway, what must traffic do when a school bus has alternating red lights flashing?","a":["Only traffic behind the bus stops","Traffic in both directions stops","Only oncoming traffic stops","Traffic may pass at 30 km/h"],"correct":1,"why":"On an undivided roadway, traffic approaching from both directions must stop for the school bus."},{"cat":"Sharing the Road","q":"On a divided highway with a median, who must stop for a school bus with red lights flashing?","a":["Traffic in both directions","Only traffic behind the bus on the same side of the median","Only oncoming traffic","Nobody"],"correct":1,"why":"On a divided highway, vehicles behind the bus on its side of the median must stop; opposing traffic is separated by the median."},{"cat":"Sharing the Road","q":"About how far from a stopped school bus should you stop?","a":["2 metres","5 metres","20 metres","50 metres"],"correct":2,"why":"The guide directs drivers to stop about 20 metres from the school bus."},{"cat":"Sharing the Road","q":"When may you move again after stopping for a school bus?","a":["As soon as the door closes","When the alternating red lights stop flashing","When another vehicle moves","After one minute"],"correct":1,"why":"Remain stopped until the alternating flashing red lights are no longer operating."},{"cat":"Sharing the Road","q":"When approaching a working snowplow, what is the safest general approach?","a":["Follow closely so others cannot merge","Leave a large following distance and pass only when clearly safe and permitted","Pass immediately on the right","Use high beams in the snow cloud"],"correct":1,"why":"Snowplows can create a snow cloud and spread sand or rocks. Leave plenty of space and do not pass unless it can be done safely."},{"cat":"Sharing the Road","q":"What minimum following distance should you keep behind an emergency vehicle with its lights or siren operating?","a":["30 metres","75 metres","150 metres","300 metres"],"correct":2,"why":"The guide specifies a following distance of at least 150 metres behind an operating emergency vehicle."},{"cat":"Law & Fitness","q":"Which is an example of distracted driving?","a":["Checking mirrors","Using a hand-held cell phone","Scanning an intersection","Adjusting speed for weather"],"correct":1,"why":"Using a hand-held cell phone while driving is prohibited distracted driving."},{"cat":"Law & Fitness","q":"Who is responsible for ensuring the vehicle is insured and registered before it is driven?","a":["Only the registry agent","The driver and vehicle owner must ensure legal requirements are met","Only passengers","The road-test examiner"],"correct":1,"why":"A vehicle operated on Alberta roads must be properly registered and insured, and the required documents must be available."},{"cat":"Scenarios","q":"Andy is behind a snowplow and cannot see through its snow cloud. What should he do?","a":["Move closer to see its lights","Increase the gap and wait for visibility","Pass on the shoulder","Flash high beams continuously"],"correct":1,"why":"Stay well back. The snow cloud can hide vehicles and road hazards, and the plow may spread sand or rocks."},{"cat":"Scenarios","q":"At night, Andy is 100 metres behind another vehicle. What headlights should he use?","a":["High beams","Low beams","Parking lights","No lights if the road is lit"],"correct":1,"why":"Within 150 metres of a vehicle ahead, use low-beam headlights."},{"cat":"Scenarios","q":"Andy sees an emergency vehicle approaching with lights and siren. What should he do?","a":["Speed up to stay ahead","Yield, move safely out of its path and stop as required","Stop in the intersection","Follow it closely"],"correct":1,"why":"Make room for the emergency vehicle, pull over safely and remain stopped until it has passed."},{"cat":"Licensing","q":"What is the minimum probationary period for a Class 5-GDL driver?","a":["6 months","1 year","3 years","2 years"],"correct":3,"why":"A Class 5-GDL driver must remain probationary for at least two years."},{"cat":"Licensing","q":"What is the minimum age to exit GDL and hold a full Class 5 licence?","a":["18","16","17","21"],"correct":0,"why":"A driver must be at least 18 and meet the other exit requirements."},{"cat":"Licensing","q":"To exit GDL, how long must the driver be free of suspensions or traffic violations at the end of probation?","a":["The entire two years","The last 12 months","The last 3 months","The last 6 months"],"correct":1,"why":"The final 12 months of probation must be free of suspensions and traffic violations."},{"cat":"Licensing","q":"How much can approved driver training reduce the GDL probationary stage?","a":["Up to 1 year","It cannot reduce it","Up to 6 months","Up to 1 month"],"correct":2,"why":"Approved driver education may reduce probation by up to six months when all conditions are met."},{"cat":"Licensing","q":"What endorsement shows completion of an approved driver education course?","a":["Q","S","V","U"],"correct":3,"why":"Endorsement U records completion of an approved driver education course."},{"cat":"Licensing","q":"What should you bring to a vision assessment if you use corrective lenses?","a":["Your glasses or contact lenses","A doctor’s note only","A recent photograph","Nothing extra"],"correct":0,"why":"Bring the corrective glasses or contacts you normally use."},{"cat":"Licensing","q":"About how long is the Alberta Class 5 road test, including instructions and the result summary?","a":["2 hours","45 minutes","15 minutes","90 minutes"],"correct":1,"why":"The guide describes the Class 5 road test as approximately 45 minutes."},{"cat":"Licensing","q":"Which action is an automatic road-test failure?","a":["Driving exactly at the limit","Using a turn signal early","Failing to stop completely at a stop sign","Checking mirrors too often"],"correct":2,"why":"Failing to stop completely at a stop sign is listed as an automatic failure."},{"cat":"Licensing","q":"A Class 7 learner may operate a motorcycle only when the learner is at least:","a":["18 years old","16 years old","14 years old","15 years old"],"correct":1,"why":"A Class 7 holder must be at least 16 to learn on a motorcycle with a qualified Class 6 supervisor."},{"cat":"Licensing","q":"What is required to drive a vehicle equipped with air brakes?","a":["A trailer endorsement","A motorcycle endorsement","An air-brake endorsement","A Class 7 licence only"],"correct":2,"why":"An air-brake endorsement is required for vehicles with air-only or combined air/hydraulic braking systems."},{"cat":"Licensing","q":"What letter identifies the air-brake endorsement?","a":["U","S","A","Q"],"correct":3,"why":"The Alberta air-brake endorsement is shown as Q."},{"cat":"Licensing","q":"Must a driver carry their licence while driving?","a":["Yes","Only on highways","Only during the first year","No, a photograph is enough"],"correct":0,"why":"A driver must have the licence in their possession and produce it when requested."},{"cat":"Licensing","q":"What documents may a peace officer require from a driver?","a":["Only registration","Licence, insurance and registration","Passport, birth certificate and licence","Only insurance"],"correct":1,"why":"Drivers must be able to produce their licence, insurance and registration."},{"cat":"Licensing","q":"Who must accompany a minor applying for a first Alberta driver’s licence?","a":["A driving instructor","A teacher","A parent or legal guardian","Any adult friend"],"correct":2,"why":"A parent or legal guardian must attend, prove guardianship and sign consent unless an exemption applies."},{"cat":"Licensing","q":"Can a parent or guardian revoke consent for a minor’s licence before age 18?","a":["No","Only after a collision","Only through a court order","Yes, in writing"],"correct":3,"why":"The guardian may revoke consent in writing, causing the licence to be suspended."},{"cat":"Licensing","q":"How long may a new Alberta resident use an out-of-province licence after becoming resident?","a":["90 days","30 days","6 months","1 year"],"correct":0,"why":"A new Alberta resident must exchange the licence within 90 days."},{"cat":"Licensing","q":"What must a driver disclose if it could affect safe driving?","a":["Nothing unless asked by police","A medical or physical condition","Only a vision condition","Only a seizure disorder"],"correct":1,"why":"Conditions that may affect safe operation must be disclosed."},{"cat":"Licensing","q":"What condition code indicates adequate lenses are required?","a":["U","H","A","Q"],"correct":2,"why":"Condition code A indicates adequate corrective lenses."},{"cat":"Licensing","q":"What does condition code H mean?","a":["Hand controls","Hearing aid required","Highway driving only","Daylight driving only"],"correct":3,"why":"Condition H restricts the driver to daylight driving."},{"cat":"Licensing","q":"What does condition code K mean?","a":["Automatic transmission","Corrective lenses","Outside mirrors","Periodic medical"],"correct":0,"why":"Condition K restricts the driver to an automatic transmission."},{"cat":"Licensing","q":"What must happen if a licence is lost, stolen, destroyed or unreadable?","a":["Take another road test","Apply for a replacement immediately","Wait until renewal","Carry a photocopy indefinitely"],"correct":1,"why":"The driver must apply for a replacement at a registry agent office."},{"cat":"Licensing","q":"Who is responsible for renewing a driver’s licence before it expires?","a":["The insurance company","The police","The licence holder","The registry agent"],"correct":2,"why":"Renewal is the driver’s responsibility; general mailed reminders are no longer sent."},{"cat":"Licensing","q":"Are Alberta licence plates transferred to a new owner when a vehicle is sold?","a":["Yes, always","Only for family sales","Only if insurance agrees","No, plates remain with the owner"],"correct":3,"why":"Alberta licence plates remain with the owner and are not transferable to another person."},{"cat":"Licensing","q":"What insurance is required for motor vehicles on Alberta roadways?","a":["Public liability insurance","Collision insurance only","Comprehensive insurance only","No insurance for learners"],"correct":0,"why":"All motor vehicles must carry public liability insurance."},{"cat":"Signals","q":"What is the order of lights on a vertical traffic signal from top to bottom?","a":["Yellow, red, green","Red, yellow, green","Green, yellow, red","Red, green, yellow"],"correct":1,"why":"Vertical signals place red at the top, yellow in the centre and green at the bottom."},{"cat":"Signals","q":"What is the order of lights on a horizontal traffic signal from left to right?","a":["Yellow, red, green","Red, green, yellow","Red, yellow, green","Green, yellow, red"],"correct":2,"why":"Horizontal signals place red on the left, yellow in the centre and green on the right."},{"cat":"Signals","q":"What does a green arrow shown with a red light permit?","a":["Movement in every direction","A U-turn only","No movement","Movement only in the arrow’s direction"],"correct":3,"why":"The driver may proceed without stopping only in the direction of the green arrow."},{"cat":"Signals","q":"What does a flashing green traffic light mean in Alberta?","a":["You may proceed or turn, while still yielding to lawful road users","Treat it as a four-way stop","Stop before proceeding","The signal is broken"],"correct":0,"why":"Opposing traffic faces red, but drivers must still yield to pedestrians or vehicles lawfully in the intersection."},{"cat":"Signals","q":"When yellow pedestrian-crossing lights are flashing, what maximum speed applies?","a":["50 km/h","30 km/h","20 km/h","40 km/h"],"correct":1,"why":"Drivers must reduce speed to a maximum of 30 km/h and yield or stop for pedestrians."},{"cat":"Signals","q":"A pedestrian who has already entered when DON’T WALK appears should:","a":["Stop in the roadway","Run regardless of safety","Continue and clear the crosswalk","Return to the curb immediately"],"correct":2,"why":"A pedestrian already crossing may continue and clear the crosswalk."},{"cat":"Signs & Speed","q":"What does an octagonal sign mean?","a":["Yield","Railway crossing","School zone","Stop"],"correct":3,"why":"The eight-sided red sign means come to a complete stop."},{"cat":"Signs & Speed","q":"What shape is a yield sign?","a":["Downward-pointing triangle","Octagon","Pentagon","Diamond"],"correct":0,"why":"A yield sign is an inverted triangle."},{"cat":"Signs & Speed","q":"What shape identifies a school zone or school area?","a":["Horizontal rectangle","Pentagon","Circle","Octagon"],"correct":1,"why":"School-zone and school-area signs use a pentagon shape."},{"cat":"Signs & Speed","q":"What does a yellow diamond sign generally indicate?","a":["A service location","A route number","A warning or hazard","A mandatory action"],"correct":2,"why":"Yellow diamond signs warn of hazards or changing roadway conditions."},{"cat":"Signs & Speed","q":"What do white symbols or words on a green rectangle usually provide?","a":["A prohibition","A construction warning","A school-zone rule","Destination or route guidance"],"correct":3,"why":"Green guide signs provide directional and destination information."},{"cat":"Signs & Speed","q":"What do white symbols or words on a blue sign usually indicate?","a":["Services or assistance","A mandatory stop","A speed limit","A railway crossing"],"correct":0,"why":"Blue information signs point to services such as fuel, food, lodging or assistance."},{"cat":"Signs & Speed","q":"What does a WRONG WAY sign tell you?","a":["Passing is prohibited","Traffic is moving toward you in that direction","The road has rough pavement","You must make a U-turn"],"correct":1,"why":"A WRONG WAY sign indicates that entering would place you against oncoming traffic."},{"cat":"Signs & Speed","q":"At a yield sign, what must a driver do?","a":["Speed up to merge first","Ignore pedestrians outside a marked crosswalk","Yield to traffic and pedestrians with right-of-way","Always stop for five seconds"],"correct":2,"why":"The driver must yield to traffic not facing the sign and to pedestrians waiting or crossing."},{"cat":"Signs & Speed","q":"What does a DO NOT ENTER sign mean?","a":["Enter only during daylight","Yield before entering","Road ends ahead","Do not enter the roadway or lane"],"correct":3,"why":"The sign prohibits entry from that direction."},{"cat":"Signs & Speed","q":"What does a black-and-white ONE WAY sign indicate?","a":["Traffic travels only in the arrow’s direction","The road has one lane","Passing is prohibited","Only buses may enter"],"correct":0,"why":"A one-way sign identifies the permitted direction of traffic flow."},{"cat":"Signs & Speed","q":"What does a DIVIDED HIGHWAY BEGINS sign warn?","a":["A bridge is opening","A median will separate opposing traffic","The roadway narrows to one lane","A railway crossing is ahead"],"correct":1,"why":"The sign warns that opposing traffic will soon be separated by a median."},{"cat":"Signs & Speed","q":"What does a DIVIDED HIGHWAY ENDS sign warn?","a":["A freeway begins","The speed limit ends","Opposing traffic will no longer be separated by a median","The highway is closed"],"correct":2,"why":"The driver should prepare for opposing traffic on an undivided roadway."},{"cat":"Signs & Speed","q":"What does a checkerboard sign usually mark?","a":["A pedestrian crossing","A hospital","A passing lane","The end of a roadway or a sharp change in direction"],"correct":3,"why":"Checkerboard signs warn that the roadway ends or changes direction sharply."},{"cat":"Signs & Speed","q":"What does a slow-moving vehicle emblem look like?","a":["An orange triangle with a red border","A yellow circle","A blue square","A white octagon"],"correct":0,"why":"Slow-moving vehicles display an orange triangle bordered in red."},{"cat":"Zones","q":"When is a school-zone speed limit normally in effect unless local signs say otherwise?","a":["Only during winter","On school days during posted times","Every day from sunrise to sunset","Only when children are visible"],"correct":1,"why":"School-zone signs and local rules establish the applicable school-day times; drivers must follow the posted information."},{"cat":"Zones","q":"What is the usual maximum speed in an Alberta playground zone unless otherwise posted?","a":["40 km/h","50 km/h","30 km/h","20 km/h"],"correct":2,"why":"The usual playground-zone maximum is 30 km/h during the times shown by law or sign."},{"cat":"Zones","q":"May a driver pass another vehicle travelling in the same direction in a school or playground zone while the restriction is in effect?","a":["Yes, below 30 km/h","Yes, if no children are visible","Only motorcycles may pass","No"],"correct":3,"why":"Passing another vehicle travelling in the same direction is prohibited while the zone restriction is in effect."},{"cat":"Signs & Speed","q":"What do orange signs indicate?","a":["Construction or maintenance information","Hospital services","School areas","Permitted actions"],"correct":0,"why":"Orange signs identify temporary construction and maintenance conditions."},{"cat":"Signs & Speed","q":"What should a driver do when approaching a flag person in a construction zone?","a":["Drive around the flag person","Obey the flag person’s directions","Follow only traffic lights","Stop only if another driver stops"],"correct":1,"why":"Flag persons have authority to direct traffic through a work zone."},{"cat":"Signs & Speed","q":"Fines for speeding in a construction zone may be:","a":["Reduced by half","The same in every circumstance","Doubled when workers are present","Waived for learners"],"correct":2,"why":"Construction zones may carry doubled speeding fines when workers are present, as indicated."},{"cat":"Signs & Speed","q":"What does a solid yellow line separate?","a":["Traffic moving in the same direction","Parking spaces","A bicycle lane from a sidewalk","Traffic moving in opposite directions"],"correct":3,"why":"Yellow centre lines separate opposing traffic streams."},{"cat":"Signs & Speed","q":"What does a solid white line generally separate?","a":["Lanes moving in the same direction where lane changes are discouraged or restricted","Opposing traffic","A railway crossing","A shoulder from a ditch only"],"correct":0,"why":"White lines divide traffic moving in the same direction; a solid line signals that crossing is restricted or discouraged."},{"cat":"Signs & Speed","q":"What does a broken white line mean?","a":["The lane is closing immediately","Lane changes are permitted when safe","Passing is never allowed","Traffic moves in opposite directions"],"correct":1,"why":"A broken white line separates same-direction lanes and may be crossed when safe."},{"cat":"Signs & Speed","q":"What does a double solid yellow line mean?","a":["The road is one-way","Only trucks may cross","Do not cross to pass in either direction","Passing is allowed both ways"],"correct":2,"why":"Double solid yellow lines prohibit crossing to pass in either direction."},{"cat":"Signs & Speed","q":"What do white diamond pavement markings usually indicate?","a":["A railway crossing","A no-parking area","A school zone","A reserved or special-use lane"],"correct":3,"why":"Diamond symbols identify lanes reserved for specific users or vehicles."},{"cat":"Signs & Speed","q":"What does a painted bicycle symbol in a lane indicate?","a":["A bicycle lane or shared-use facility","Motorcycles only","No bicycles allowed","A pedestrian-only path"],"correct":0,"why":"The bicycle symbol identifies a lane or roadway space intended for bicycle use."},{"cat":"Signs & Speed","q":"What is a shared-use lane marking sometimes called?","a":["A lane X","A sharrow","A chevron stop","A rumble bar"],"correct":1,"why":"A bicycle symbol with chevrons is commonly called a sharrow and reminds users to share the lane."},{"cat":"Driving Basics","q":"Before driving, what should be adjusted first for a safe seating position?","a":["Navigation destination only","Interior lighting","Seat, head restraint and mirrors","Radio and climate controls"],"correct":2,"why":"A safe pre-drive setup includes correct seating, head restraint and mirror adjustment."},{"cat":"Driving Basics","q":"Where should the top of the head restraint be positioned?","a":["At shoulder height","At the base of the neck","Below the ears","At least level with the top of the ears"],"correct":3,"why":"The restraint should support the head and be at least as high as the top of the ears."},{"cat":"Driving Basics","q":"Why should loose objects be secured before driving?","a":["They can become dangerous projectiles in a sudden stop or collision","They always damage upholstery","They reduce fuel economy greatly","They make mirrors inaccurate"],"correct":0,"why":"Unsecured cargo can strike occupants during sudden movement."},{"cat":"Driving Basics","q":"What should you check around the vehicle before getting in?","a":["Nothing if the vehicle has a camera","Children, animals, obstacles, leaks and vehicle condition","Only tire colour","Only the licence plate"],"correct":1,"why":"A walk-around can reveal hazards, obstacles or mechanical problems cameras may miss."},{"cat":"Driving Basics","q":"What is the purpose of the parking brake?","a":["To replace the service brakes","To hold the accelerator steady","To help secure a parked vehicle","To stop faster at highway speed"],"correct":2,"why":"The parking brake helps keep a parked vehicle from moving."},{"cat":"Driving Basics","q":"When moving an automatic transmission from Park, what should you normally do?","a":["Press the accelerator","Release the steering wheel","Turn off the engine","Press the brake pedal"],"correct":3,"why":"The brake should be applied while selecting a drive gear."},{"cat":"Driving Basics","q":"What does engine braking mean?","a":["Using a lower gear to help reduce speed","Turning the engine off while moving","Pumping the accelerator","Applying only the parking brake"],"correct":0,"why":"A lower gear lets engine resistance assist with slowing, especially on long grades."},{"cat":"Driving Basics","q":"For ordinary steering, where should the hands generally be placed?","a":["One hand on the gear selector","Around 9 and 3 o’clock","At 12 o’clock with one hand","Both at 6 o’clock"],"correct":1,"why":"A balanced 9-and-3 position supports control and reduces airbag-related injury risk."},{"cat":"Driving Basics","q":"When should a turn signal be used?","a":["Only at traffic lights","Only for left turns","Before turning, changing lanes, pulling away or moving to the curb","Only when another vehicle is close"],"correct":2,"why":"Signals communicate intended movement to other road users."},{"cat":"Driving Basics","q":"Does signalling give a driver the right-of-way?","a":["Yes, immediately","Only on highways","Only if signalling for three seconds","No"],"correct":3,"why":"A signal communicates intent; the driver must still ensure the movement is safe and yield as required."},{"cat":"Driving Basics","q":"What is the safest way to accelerate from a stop?","a":["Smoothly and gradually","As quickly as possible","With the wheels turned","By looking only in the rear-view mirror"],"correct":0,"why":"Smooth acceleration preserves traction and gives others time to respond."},{"cat":"Driving Basics","q":"What three factors make up total stopping distance?","a":["Weight, colour and engine size","Perception, reaction and braking distance","Speed, fuel and tire pressure","Steering, signalling and parking"],"correct":1,"why":"Total stopping distance includes seeing the hazard, reacting and the vehicle’s braking distance."},{"cat":"Driving Basics","q":"What happens to stopping distance as speed increases?","a":["It decreases","Only reaction distance changes","It increases greatly","It stays the same"],"correct":2,"why":"Higher speed increases both distance travelled during reaction and braking distance."},{"cat":"Driving Basics","q":"Which condition increases stopping distance?","a":["Dry pavement with good tires","Lower speed","More following distance","Wet or icy pavement"],"correct":3,"why":"Reduced traction increases the distance needed to stop."},{"cat":"Driving Basics","q":"When reversing, where should you look?","a":["In the direction of travel, using mirrors and direct observation","Only at the backup camera","Only forward","Only in the left mirror"],"correct":0,"why":"Drivers must look behind and around the vehicle; cameras are aids, not substitutes for observation."},{"cat":"Driving Basics","q":"When backing from a driveway, who must you yield to?","a":["Only cyclists","Pedestrians and traffic on the roadway","Only vehicles from the left","No one if reversing slowly"],"correct":1,"why":"A vehicle entering a roadway from private property must yield to road users and pedestrians."},{"cat":"Driving Basics","q":"What is the safest choice when visibility behind the vehicle is poor?","a":["Rely entirely on sensors","Sound the horn and continue","Get out and check or use a guide when appropriate","Reverse faster"],"correct":2,"why":"Confirming the path is clear prevents backing collisions."},{"cat":"Parking","q":"When parallel parking, how close should the vehicle generally be to the curb?","a":["Within 1.5 m","Touching the curb","At least 1 m away","Within 50 cm"],"correct":3,"why":"The guide requires the vehicle to be parked close to and parallel with the curb, generally within 50 cm."},{"cat":"Parking","q":"When parking uphill with a curb, which way should the front wheels point?","a":["Away from the curb","Toward the curb","Straight ahead","Toward the centre line"],"correct":0,"why":"If the vehicle rolls backward, the tire should catch the curb."},{"cat":"Parking","q":"When parking downhill with a curb, which way should the front wheels point?","a":["Toward the centre line","Toward the curb","Away from the curb","Straight ahead"],"correct":1,"why":"Turning toward the curb helps prevent the vehicle from rolling into traffic."},{"cat":"Parking","q":"When parking uphill without a curb, which way should the wheels point?","a":["Straight ahead","Any direction","Toward the edge of the road","Toward the centre line"],"correct":2,"why":"Turn toward the road edge so a rolling vehicle moves away from traffic."},{"cat":"Parking","q":"Before leaving a parked vehicle, what should you do?","a":["Leave it in neutral","Keep the engine running","Turn the wheels toward traffic","Set the parking brake and secure the transmission"],"correct":3,"why":"The vehicle should be secured against movement before occupants leave."},{"cat":"Parking","q":"Is parking permitted in front of a driveway?","a":["No","Yes for five minutes","Only at night","Only with hazard lights"],"correct":0,"why":"Parking must not block a driveway."},{"cat":"Parking","q":"Is parking permitted on a crosswalk?","a":["Only motorcycles may park there","No","Yes if no pedestrians are present","Only outside school hours"],"correct":1,"why":"A vehicle must not be parked on a crosswalk."},{"cat":"Parking","q":"What is angle parking?","a":["Parking on a hill","Parking partly on a sidewalk","Parking at an angle to the curb in marked spaces","Parking parallel to the curb"],"correct":2,"why":"Angle parking uses spaces marked diagonally or at right angles to the curb."},{"cat":"Intersections","q":"Who has right-of-way when entering a roadway from an alley, driveway or parking lot?","a":["The entering vehicle","The largest vehicle","Whoever signals first","Traffic and pedestrians already on the roadway or sidewalk"],"correct":3,"why":"A driver entering from private property must yield to road users and pedestrians."},{"cat":"Intersections","q":"At an uncontrolled intersection, who normally yields when two vehicles arrive at about the same time?","a":["The driver on the left yields to the driver on the right","The driver on the right yields to the left","The faster driver yields","The larger vehicle goes first"],"correct":0,"why":"At an uncontrolled intersection, yield to the vehicle on your right when arrivals are approximately simultaneous."},{"cat":"Intersections","q":"At a four-way stop, who normally proceeds first?","a":["The vehicle travelling straight","The vehicle that stopped first","The vehicle on the left","The largest vehicle"],"correct":1,"why":"The first vehicle to stop is normally first to proceed, after confirming it is safe."},{"cat":"Intersections","q":"At a four-way stop when two vehicles stop at the same time, who yields?","a":["Both must reverse","The vehicle turning right always yields","The driver on the left yields to the driver on the right","The driver on the right yields to the left"],"correct":2,"why":"The same-time rule requires the driver on the left to yield to the driver on the right."},{"cat":"Intersections","q":"May you enter an intersection if traffic is backed up and you cannot clear it?","a":["Yes if the light is green","Yes if you are turning right","Only during rush hour","No"],"correct":3,"why":"Do not block an intersection; wait until there is room beyond it."},{"cat":"Intersections","q":"What is the key rule when entering a roundabout?","a":["Yield to traffic already in the roundabout","Stop inside the roundabout","Enter before trucks","Traffic in the roundabout yields to entering traffic"],"correct":0,"why":"Entering drivers yield to vehicles already circulating and to pedestrians as required."},{"cat":"Intersections","q":"Which direction does traffic move in an Alberta roundabout?","a":["It changes by time of day","Counter-clockwise","Clockwise","Either direction"],"correct":1,"why":"Traffic circulates counter-clockwise around the centre island."},{"cat":"Intersections","q":"Should you change lanes inside a roundabout?","a":["Yes, without signalling","Only if driving slowly","Avoid it; choose the correct lane before entering","Always change lanes before exiting"],"correct":2,"why":"Drivers should select the proper lane before entering and maintain it through the roundabout."},{"cat":"Intersections","q":"When should you signal in a roundabout?","a":["Signal left the entire time","Do not signal at all","Use hazard lights","Signal right before exiting"],"correct":3,"why":"A right signal communicates the intended exit."},{"cat":"Intersections","q":"When turning right, which lane should you normally enter?","a":["The first available lane to the right","Any lane","The far-left lane","The shoulder"],"correct":0,"why":"Complete the turn into the nearest lawful lane unless signs or markings direct otherwise."},{"cat":"Intersections","q":"When turning left from a two-way road onto a two-way road, which lane should you enter?","a":["The shoulder","The lane immediately to the right of the centre line","The far-right lane","Any open lane"],"correct":1,"why":"A left turn should normally end in the nearest lawful lane on the new roadway."},{"cat":"Intersections","q":"Before turning left, what must you yield to?","a":["Only vehicles already stopped","No one when the light is green","Oncoming traffic and pedestrians","Only trucks"],"correct":2,"why":"A green light does not remove the duty to yield to oncoming traffic and pedestrians while turning left."},{"cat":"Intersections","q":"What is a two-way left-turn lane used for?","a":["Passing slow vehicles","Through travel","Parking","Left turns by vehicles travelling in either direction"],"correct":3,"why":"The centre lane is shared for preparing and completing left turns, not for general travel or passing."},{"cat":"Intersections","q":"May you travel for a long distance in a two-way left-turn lane?","a":["No","Yes at any speed","Only at night","Only if traffic is heavy"],"correct":0,"why":"The lane is for turning movements, not through travel."},{"cat":"Intersections","q":"When may a U-turn be made?","a":["On a curve with limited visibility","Only where legal and safe","Anywhere if traffic is light","At every traffic light"],"correct":1,"why":"U-turns are restricted and must only be made where permitted and safe."},{"cat":"Intersections","q":"Is a U-turn permitted at a traffic-light-controlled intersection unless a sign allows it?","a":["Only for motorcycles","Only during daylight","No","Yes"],"correct":2,"why":"U-turns at signal-controlled intersections are prohibited unless a sign specifically permits them."},{"cat":"Intersections","q":"Is a U-turn permitted on a curve or near the crest of a hill when visibility is limited?","a":["Yes if signalling","Only under 30 km/h","Only on rural roads","No"],"correct":3,"why":"Limited sight distance makes a U-turn unsafe and prohibited."},{"cat":"Highways","q":"On a multi-lane highway, which lane should slower traffic generally use?","a":["The right lane","The left lane","The shoulder","Any lane regardless of traffic"],"correct":0,"why":"Keep right except when passing, turning left or when lane use requires otherwise."},{"cat":"Highways","q":"What should you do before changing lanes?","a":["Brake sharply","Check mirrors, signal and shoulder-check the blind spot","Signal only","Honk and move immediately"],"correct":1,"why":"A safe lane change requires observation, signalling and a blind-spot check."},{"cat":"Highways","q":"When passing another vehicle, when should you return to your lane?","a":["While beside the vehicle","Only after slowing below its speed","When you can see the passed vehicle in your inside rear-view mirror and it is safe","As soon as your front bumper is ahead"],"correct":2,"why":"Leave enough clearance before moving back into the lane."},{"cat":"Highways","q":"Where is passing prohibited?","a":["Where signs or pavement markings prohibit it or sight distance is insufficient","On every straight road","Whenever the road is dry","Only near cities"],"correct":0,"why":"Do not pass when prohibited or where you cannot see far enough to complete the manoeuvre safely."},{"cat":"Highways","q":"What should a driver being passed do?","a":["Brake hard","Maintain a steady speed and allow the pass","Speed up","Move left"],"correct":1,"why":"A steady, predictable speed helps the passing vehicle complete the manoeuvre safely."},{"cat":"Highways","q":"What is the emergency stopping lane or highway shoulder intended for?","a":["Slow vehicles at all times","Parking for phone calls","Emergencies and stopped vehicles, not ordinary travel","Routine passing"],"correct":2,"why":"The shoulder is not a normal travel or passing lane."},{"cat":"Highways","q":"When entering a freeway, where should you build speed?","a":["On the shoulder","After entering the through lane","At the end of the ramp while stopped","In the acceleration lane"],"correct":3,"why":"Use the acceleration lane to match the speed of freeway traffic before merging."},{"cat":"Highways","q":"Who has right-of-way when you merge onto a freeway?","a":["Traffic already on the freeway","The merging vehicle","The larger vehicle","Whichever driver signals first"],"correct":0,"why":"The entering driver must find a safe gap and yield to traffic already on the major roadway."},{"cat":"Highways","q":"What should you do if you miss a freeway exit?","a":["Make a U-turn through the median","Continue to the next exit","Reverse on the shoulder","Stop in the travel lane"],"correct":1,"why":"Never stop or reverse; continue safely to the next exit."},{"cat":"Highways","q":"When leaving a freeway, when should you reduce speed?","a":["Only after stopping","Never","After entering the deceleration lane, unless conditions require earlier action","In the through lane before the exit"],"correct":2,"why":"Move into the exit lane first, then slow according to the ramp and conditions."},{"cat":"Highways","q":"Why should you leave extra space behind a large truck?","a":["To draft and save fuel","Because trucks always stop faster","To prevent the truck from changing lanes","To improve visibility and stay out of its blind spot"],"correct":3,"why":"Extra distance improves sight lines and gives more time to respond."},{"cat":"Hazards","q":"If emergency braking is needed in a vehicle with ABS, what should you do?","a":["Press the brake firmly and keep steady pressure","Pump the brake rapidly","Use only the parking brake","Release the brake whenever it vibrates"],"correct":0,"why":"ABS may pulse; maintain firm pressure and steer where you want to go."},{"cat":"Hazards","q":"If a vehicle without ABS begins to skid during hard braking, what should you do?","a":["Apply the parking brake fully","Ease brake pressure enough to regain steering, then brake again","Press harder and lock the wheels","Turn off the engine"],"correct":1,"why":"Locked wheels cannot steer; controlled braking helps regain traction."},{"cat":"Hazards","q":"If the rear wheels skid, where should you steer?","a":["Straight ahead without looking","Toward the ditch","In the direction you want the front of the vehicle to go","Directly opposite the skid at all times"],"correct":2,"why":"Look and steer toward the intended path while easing off the cause of the skid."},{"cat":"Hazards","q":"What is the first response to hydroplaning?","a":["Brake hard","Turn sharply","Accelerate","Ease off the accelerator and steer smoothly"],"correct":3,"why":"Sudden braking or steering can worsen loss of traction; reduce speed smoothly."},{"cat":"Hazards","q":"If a front tire blows out, what should you do?","a":["Hold the steering wheel firmly, ease off the accelerator and slow gradually","Brake as hard as possible","Turn sharply onto the shoulder","Accelerate to stabilize the tire"],"correct":0,"why":"Maintain control and reduce speed gradually before moving off the roadway."},{"cat":"Hazards","q":"If the accelerator sticks, what should you do?","a":["Use the parking brake only","Shift to neutral, brake and move safely off the road","Turn the key to steering lock immediately","Pump the accelerator and speed up"],"correct":1,"why":"Neutral disconnects engine power from the wheels; then brake and stop safely."},{"cat":"Hazards","q":"If the brakes fail, which action may help slow the vehicle?","a":["Accelerate uphill regardless of traffic","Open the doors","Shift to a lower gear and carefully use the parking brake","Turn off all lights"],"correct":2,"why":"Downshifting and controlled parking-brake use may reduce speed while seeking a safe escape path."},{"cat":"Hazards","q":"If the engine overheats, what should you avoid doing immediately?","a":["Turning off accessories","Stopping safely","Allowing the engine to cool","Removing a hot radiator cap"],"correct":3,"why":"Opening a hot cooling system can release scalding steam or coolant."},{"cat":"Hazards","q":"In fog, which headlights should you use?","a":["Low beams","High beams","Parking lights only","No lights"],"correct":0,"why":"High beams reflect off fog and reduce visibility; low beams are more effective."},{"cat":"Hazards","q":"At night, how should speed relate to headlight visibility?","a":["Follow the vehicle ahead closely","Drive slowly enough to stop within the illuminated distance","Drive at the posted limit regardless of visibility","Use high beams in all traffic"],"correct":1,"why":"You must be able to stop within the distance you can see."},{"cat":"Hazards","q":"What should you do when approaching glare from oncoming headlights?","a":["Close one eye and accelerate","Move toward the centre line","Look toward the right edge of your lane and reduce speed","Look directly at the headlights"],"correct":2,"why":"Using the right road edge as a guide helps avoid glare while maintaining lane position."},{"cat":"Hazards","q":"What should you do on icy or snowy roads?","a":["Use cruise control","Brake late and firmly","Follow closely to use tire tracks","Reduce speed, increase following distance and make smooth inputs"],"correct":3,"why":"Low traction requires more space and gentle steering, acceleration and braking."},{"cat":"Hazards","q":"Should cruise control be used on slippery roads?","a":["No","Yes, always","Only above 80 km/h","Only downhill"],"correct":0,"why":"Cruise control can worsen wheel spin or loss of control on slippery surfaces."},{"cat":"Hazards","q":"What is black ice?","a":["A road marking","A thin, often nearly invisible layer of ice","Dirty snow at the curb","Ice found only on bridges"],"correct":1,"why":"Black ice can be difficult to see and dramatically reduces traction."},{"cat":"Hazards","q":"Where may icy conditions form first?","a":["Only at intersections","Only in parking lots","Bridges, shaded areas and overpasses","Only on gravel roads"],"correct":2,"why":"Elevated and shaded surfaces often cool and freeze before surrounding pavement."},{"cat":"Hazards","q":"If an animal appears on the road, what should you generally do?","a":["Always swerve sharply","Accelerate past it","Turn off headlights","Brake firmly while maintaining control and avoid a dangerous swerve"],"correct":3,"why":"A sudden swerve may cause a more serious collision; controlled braking is usually safer."},{"cat":"Hazards","q":"What emergency supplies are useful in winter?","a":["Warm clothing, blanket, flashlight, food, water and traction aids","Only sunglasses","Only a phone charger","No supplies are needed in cities"],"correct":0,"why":"A winter emergency kit helps occupants remain safe if stranded."},{"cat":"Hazards","q":"After a collision, what is the first priority?","a":["Post photos online","Protect people and prevent further collisions","Assign blame","Move every injured person immediately"],"correct":1,"why":"Secure the scene, assess injuries and call for help as required."},{"cat":"Hazards","q":"Should a seriously injured person be moved after a collision?","a":["Never under any circumstance","Only to exchange information","Only when necessary to protect them from immediate danger","Always"],"correct":2,"why":"Unnecessary movement can worsen injuries; move only to escape an immediate hazard."},{"cat":"Hazards","q":"What should drivers do when an emergency vehicle approaches with lights or siren?","a":["Speed up to stay ahead","Stop in the intersection","Follow closely behind it","Yield and move safely to the side, then stop"],"correct":3,"why":"Drivers must clear a path and stop safely for the emergency vehicle."},{"cat":"Hazards","q":"After an emergency vehicle passes, how closely may you follow?","a":["Do not follow closely; keep the legally required distance","Immediately behind it","Within one car length","Close enough to pass traffic"],"correct":0,"why":"Following closely is dangerous and prohibited; maintain a substantial safe distance."},{"cat":"Hazards","q":"When passing a stopped emergency or tow vehicle with flashing lights, what should you do?","a":["Sound the horn continuously","Move over when safe and slow to the required speed","Maintain speed in the nearest lane","Stop beside it"],"correct":1,"why":"Alberta’s roadside-worker rules require drivers to slow and, where possible, move away from the stopped vehicle."},{"cat":"Hazards","q":"What should you do around snowplows and road-maintenance vehicles?","a":["Drive in their blind spots","Pass on the right shoulder","Give them extra room and do not pass unless it is clearly safe","Follow closely for a clearer road"],"correct":2,"why":"These vehicles may create snow clouds, spread material and have large blind spots."},{"cat":"Responsible Driving","q":"How far ahead should a driver scan in an urban area?","a":["At least 12 to 15 seconds","One second","Only to the vehicle ahead","Exactly 100 metres in all conditions"],"correct":0,"why":"Looking well ahead gives time to identify changing traffic and hazards."},{"cat":"Responsible Driving","q":"What is a space cushion?","a":["A parking buffer only","Open space maintained around the vehicle","The padding in an airbag","A lane reserved for buses"],"correct":1,"why":"Space around the vehicle provides escape options and reaction time."},{"cat":"Responsible Driving","q":"What minimum following interval is commonly recommended in good conditions?","a":["Half a second","10 metres at every speed","At least 3 seconds","1 second"],"correct":2,"why":"A minimum three-second interval gives basic reaction space in favourable conditions."},{"cat":"Responsible Driving","q":"When should following distance be increased?","a":["Only when driving below the limit","Never on city streets","Only when carrying passengers","In poor weather, darkness, heavy traffic or when following large vehicles"],"correct":3,"why":"Reduced visibility, traction or sight lines require extra time and space."},{"cat":"Responsible Driving","q":"What should you do if another driver is following too closely?","a":["Increase space ahead and allow them to pass when safe","Brake-check them","Speed far above the limit","Block passing lanes"],"correct":0,"why":"More space ahead lets you slow gradually and reduces the chance of being rear-ended."},{"cat":"Responsible Driving","q":"Why should drivers check mirrors regularly?","a":["Because mirrors remove all blind spots","To maintain awareness of traffic beside and behind them","To avoid looking ahead","To monitor passengers only"],"correct":1,"why":"Mirror checks are part of continuous 360-degree awareness, but shoulder checks are still needed."},{"cat":"Responsible Driving","q":"What is a blind spot?","a":["The area directly ahead","A road without lights","An area around the vehicle not visible in mirrors","A dirty windshield only"],"correct":2,"why":"Mirrors do not show every area beside and behind a vehicle."},{"cat":"Responsible Driving","q":"Who must wear a seat belt when one is available?","a":["Only the driver","Only front-seat occupants","Only people under 18","Every occupant"],"correct":3,"why":"Drivers must ensure passengers are properly secured, and all occupants must use available restraints."},{"cat":"Responsible Driving","q":"Who is responsible for ensuring passengers under 16 are properly restrained?","a":["The driver","The youngest passenger","The vehicle owner only","The front passenger"],"correct":0,"why":"The driver is responsible for passengers under age 16."},{"cat":"Responsible Driving","q":"Where is the safest place for most children under 13?","a":["Any seat without a belt","The rear seat","The front passenger seat","The cargo area"],"correct":1,"why":"The rear seat generally provides better protection from frontal impact and airbags."},{"cat":"Responsible Driving","q":"What child restraint should be used?","a":["A booster only for every child","No restraint on short trips","One appropriate for the child’s age, weight and height and installed correctly","Any adult seat belt from birth"],"correct":2,"why":"Child restraints must match the child and be used according to manufacturer and legal requirements."},{"cat":"Responsible Driving","q":"May passengers ride in a trailer being towed?","a":["Yes below 50 km/h","Only adults","Only on rural roads","No"],"correct":3,"why":"A towed trailer is not a safe passenger compartment."},{"cat":"Responsible Driving","q":"Which driving habit improves fuel efficiency and safety?","a":["Smooth acceleration and anticipating stops","Rapid acceleration and hard braking","Long idling","Carrying unnecessary weight"],"correct":0,"why":"Smooth, planned driving reduces fuel use and abrupt manoeuvres."},{"cat":"Responsible Driving","q":"What should you do before opening a vehicle door into traffic?","a":["Turn on high beams","Check mirrors and the blind spot for cyclists and vehicles","Open it quickly","Sound the horn"],"correct":1,"why":"A door can seriously injure a cyclist or obstruct traffic."},{"cat":"Sharing the Road","q":"Who is considered a vulnerable road user?","a":["Only emergency responders","Anyone inside a large vehicle","Pedestrians, cyclists and motorcyclists","Only truck drivers"],"correct":2,"why":"Vulnerable users have less physical protection in a collision."},{"cat":"Sharing the Road","q":"At a marked or unmarked crosswalk, what must drivers do for pedestrians?","a":["Proceed if there is no traffic light","Honk so they wait","Pass another stopped vehicle","Yield and stop as required"],"correct":3,"why":"Drivers must yield to pedestrians crossing or indicating an intention to cross where required."},{"cat":"Sharing the Road","q":"May you pass a vehicle stopped at a crosswalk for a pedestrian?","a":["No","Yes on the left","Yes below 30 km/h","Only on a multi-lane road"],"correct":0,"why":"The stopped vehicle may be shielding a pedestrian from view."},{"cat":"Sharing the Road","q":"How much room should you give a cyclist when passing?","a":["Only one mirror width","As much space as practical and legally required","A few centimetres","No extra room in a marked lane"],"correct":1,"why":"Cyclists may need to avoid debris or wind; pass only with ample safe clearance."},{"cat":"Sharing the Road","q":"Why should you check for cyclists before turning right?","a":["Bicycles cannot use roads","Right turns have automatic priority","A cyclist may be travelling straight beside you","Cyclists must always stop behind cars"],"correct":2,"why":"A cyclist on the right may be hidden in a blind spot and may have right-of-way."},{"cat":"Sharing the Road","q":"What should a driver do before crossing a bicycle lane to turn?","a":["Stop in the bicycle lane and wait","Accelerate across without looking","Use the lane as a passing lane","Check, signal and yield to cyclists"],"correct":3,"why":"Drivers must cross bicycle facilities only when safe and yield to users already there."},{"cat":"Sharing the Road","q":"Why are motorcycles easy to misjudge?","a":["Their smaller size can make speed and distance difficult to estimate","They always travel slowly","They stop instantly","They have no blind spots"],"correct":0,"why":"Small visual size can make an approaching motorcycle seem farther away or slower than it is."},{"cat":"Sharing the Road","q":"Should a motorcycle be given a full lane?","a":["Only at night","Yes","No, cars may share beside it","Only above 80 km/h"],"correct":1,"why":"A motorcycle is entitled to a full lane and may need room to avoid hazards."},{"cat":"Sharing the Road","q":"Where are a large truck’s blind spots?","a":["Only on the left","Trucks have no blind spots","In front, behind and along both sides, especially the right side","Only directly behind"],"correct":2,"why":"Large vehicles have extensive no-zones around the cab and trailer."},{"cat":"Sharing the Road","q":"Why should you not cut closely in front of a large truck?","a":["It can stop faster than a car","The driver sits too low to see you","Trucks cannot change speed","It needs much more distance to stop"],"correct":3,"why":"Heavy vehicles require long stopping distances and may lose sight of a vehicle close ahead."},{"cat":"Sharing the Road","q":"When a truck turns right, why might it first move left?","a":["To create room for the trailer to clear the corner","To let cars pass on the right","Because it is changing lanes","To avoid using signals"],"correct":0,"why":"Long vehicles often swing wide; never squeeze between the truck and curb."},{"cat":"Sharing the Road","q":"What should you do when meeting a school bus with alternating red lights flashing on an undivided road?","a":["Stop only if children are visible","Stop in both directions","Only traffic behind the bus stops","Proceed at 30 km/h"],"correct":1,"why":"On an undivided road, traffic approaching from either direction must stop for the flashing red lights."},{"cat":"Sharing the Road","q":"On a divided highway, who must stop for a school bus with flashing red lights?","a":["Only oncoming traffic","No one","Traffic travelling behind the bus on its side of the divided highway","All traffic in both directions"],"correct":2,"why":"The physical divider separates opposing traffic; vehicles behind the bus on its roadway must stop."},{"cat":"Sharing the Road","q":"What do alternating amber lights on a school bus warn?","a":["The bus is safe to pass","The bus is out of service","A railway crossing is ahead","The bus is preparing to stop"],"correct":3,"why":"Amber lights warn drivers that the bus is slowing and will soon activate red stopping lights."},{"cat":"Sharing the Road","q":"When approaching a railway crossing, what should you do?","a":["Look and listen in both directions and be prepared to stop","Accelerate to cross quickly","Stop on the tracks if traffic backs up","Rely only on gates"],"correct":0,"why":"A train may approach at any time, even where warning devices are absent or malfunctioning."},{"cat":"Sharing the Road","q":"May you drive around lowered railway gates?","a":["Only after waiting one minute","No","Yes if no train is visible","Only motorcycles may"],"correct":1,"why":"Never drive around or under a lowered gate."},{"cat":"Sharing the Road","q":"When must you avoid entering a railway crossing?","a":["Only at night","Only when a train horn sounds","When there is not enough room to clear the tracks completely","Only when lights flash"],"correct":2,"why":"Never stop on the tracks; wait until there is enough space beyond them."},{"cat":"Sharing the Road","q":"Why should you expect more than one train at a multiple-track crossing?","a":["Signals apply to only one train","Trains always travel in pairs","The first train may reverse","A second train may be hidden by the first"],"correct":3,"why":"After one train passes, another may approach on a different track."},{"cat":"Sharing the Road","q":"What should you do when approaching a snowplow producing a snow cloud?","a":["Slow down and stay well back","Pass immediately on the right","Follow closely in the cleared path","Turn off headlights"],"correct":0,"why":"The cloud can hide the plow and other traffic; visibility and traction may be poor."},{"cat":"Sharing the Road","q":"What should drivers do near a funeral procession?","a":["Pass between procession vehicles","Show courtesy and avoid cutting through it","Join it to bypass traffic lights","Honk to warn vehicles"],"correct":1,"why":"Funeral processions should be treated respectfully and not disrupted."},{"cat":"Sharing the Road","q":"What should you expect from a person using a white cane or guide dog?","a":["They must yield to all vehicles","They can see traffic lights normally","They may have limited or no vision and must be given time and right-of-way","They are directing traffic"],"correct":2,"why":"Drivers must recognize mobility aids and yield patiently to pedestrians with visual impairments."},{"cat":"Sharing the Road","q":"What is the safest approach around horseback riders or livestock on a road?","a":["Sound the horn repeatedly","Pass at full speed","Drive close so the animal sees you","Slow down, give wide clearance and avoid sudden noise"],"correct":3,"why":"Animals may startle; quiet, slow and predictable movement reduces risk."},{"cat":"Law & Fitness","q":"What should a driver do if tired or drowsy?","a":["Stop in a safe place and rest","Open a window and continue indefinitely","Turn up music and speed up","Use a phone to stay alert"],"correct":0,"why":"Fatigue impairs driving; rest is the effective response."},{"cat":"Law & Fitness","q":"Can prescription or over-the-counter medication affect driving?","a":["Only if combined with alcohol","Yes","No","Only medication marked as narcotic"],"correct":1,"why":"Many medicines can cause drowsiness, slowed reactions or impaired judgment."},{"cat":"Law & Fitness","q":"What should you do before driving after taking medication?","a":["Drink coffee to cancel effects","Drive only on highways","Read warnings and ask a pharmacist or health professional if uncertain","Assume it is safe because it is legal"],"correct":2,"why":"Legal medication can still impair driving ability."},{"cat":"Law & Fitness","q":"Is using a hand-held phone while driving permitted?","a":["Yes at red lights","Yes below 30 km/h","Yes for learners only","No"],"correct":3,"why":"Alberta distracted-driving law prohibits hand-held electronic-device use while driving, including while stopped in traffic."},{"cat":"Law & Fitness","q":"Does being stopped at a red light allow hand-held phone use?","a":["No","Yes","Only for texting","Only for social media"],"correct":0,"why":"A driver stopped in traffic is still driving for distracted-driving purposes."},{"cat":"Law & Fitness","q":"Which activity can be distracted driving even without a phone?","a":["Using a turn signal","Any activity that takes attention from driving","Checking mirrors","Scanning intersections"],"correct":1,"why":"Distraction includes visual, manual and cognitive activities that reduce driving attention."},{"cat":"Law & Fitness","q":"What is the safest rule regarding alcohol, cannabis or impairing drugs before driving?","a":["Drink coffee first","Wait ten minutes","Do not drive","Drive slowly"],"correct":2,"why":"Impairing substances reduce judgment, reaction and coordination; the safe choice is not to drive."},{"cat":"Law & Fitness","q":"Can cannabis impair driving even if it is legal?","a":["No","Only for learners","Only when smoked","Yes"],"correct":3,"why":"Legality does not remove impairment risk or driving prohibitions."},{"cat":"Law & Fitness","q":"What should you do if you are angry or emotionally upset?","a":["Calm down before driving or stop safely","Drive faster to arrive sooner","Confront other drivers","Use the horn continuously"],"correct":0,"why":"Strong emotion can impair attention, judgment and risk perception."},{"cat":"Law & Fitness","q":"What is aggressive driving?","a":["Driving below the limit in snow","Unsafe behaviour motivated by impatience, hostility or competition","Maintaining a safe following distance","Yielding to pedestrians"],"correct":1,"why":"Aggressive driving includes tailgating, unsafe lane changes, speeding and hostile actions."},{"cat":"Law & Fitness","q":"How should you respond to an aggressive driver?","a":["Block their lane","Follow them","Avoid engagement, create distance and let them go","Make eye contact and gesture"],"correct":2,"why":"Do not escalate; protect space and report serious danger when safe."},{"cat":"Law & Fitness","q":"What is the purpose of demerit points?","a":["To reward safe driving","To set insurance prices only","To replace fines","To identify and sanction repeated traffic violations"],"correct":3,"why":"Demerits accumulate for convictions and can lead to suspension."},{"cat":"Law & Fitness","q":"What can happen if a learner or probationary driver reaches 8 demerit points?","a":["The licence is suspended","They receive a full Class 5","Nothing until 15 points","Only the insurance changes"],"correct":0,"why":"Class 7 and Class 5-GDL drivers are suspended at eight or more demerit points."},{"cat":"Law & Fitness","q":"Must you obey directions from a peace officer even if traffic signals indicate something else?","a":["Only during emergencies","Yes","No","Only at night"],"correct":1,"why":"A peace officer directing traffic overrides ordinary signs and signals."},{"cat":"Law & Fitness","q":"What should you do after receiving a licence suspension notice?","a":["Drive only to work","Ask a passenger to watch for police","Stop driving as directed and comply with reinstatement requirements","Continue until the licence card expires"],"correct":2,"why":"Driving while suspended is unlawful and can lead to further penalties."},{"cat":"Law & Fitness","q":"What is SafeRoads Alberta associated with?","a":["Road construction permits","Vehicle sales","Driver education schools","Administrative sanctions for impaired driving and related matters"],"correct":3,"why":"SafeRoads Alberta administers provincial impaired-driving sanctions and review processes."},{"cat":"Towing","q":"Must a trailer travelling on Alberta roadways be registered?","a":["Yes","No if under 1,000 kg","Only for commercial use","Only outside cities"],"correct":0,"why":"Motor vehicles and trailers operated on roadways must be registered."},{"cat":"Towing","q":"Where must the trailer licence plate be displayed?","a":["On the dashboard","Securely at the rear and clearly visible","Inside the tow vehicle","On the trailer tongue"],"correct":1,"why":"The plate must be attached at the rear and visible as required."},{"cat":"Towing","q":"What must connect a trailer to the tow vehicle in addition to the main hitch?","a":["An extension cord","Nothing","Safety chains or cables","A rope only"],"correct":2,"why":"Safety chains or cables provide a backup connection if the hitch fails."},{"cat":"Towing","q":"How should safety chains be attached?","a":["Dragging on the road","Wrapped around the bumper only","Tight with no turning movement","Crossed under the trailer tongue with enough slack for turns"],"correct":3,"why":"Crossing the chains can cradle the tongue and they must permit normal turning without dragging."},{"cat":"Towing","q":"What should be checked before towing?","a":["Hitch, coupler, chains, lights, tires, load and brakes if equipped","Only fuel level","Only the tow vehicle mirrors","Only the trailer colour"],"correct":0,"why":"A complete pre-trip check helps prevent separation, tire failure and lighting or load problems."},{"cat":"Towing","q":"How should cargo in a trailer be loaded?","a":["Loose so it can settle","Evenly distributed and securely tied down","All at the rear","All on one side"],"correct":1,"why":"Balanced, secured cargo improves stability and prevents shifting."},{"cat":"Towing","q":"What may happen if too much trailer weight is placed at the rear?","a":["Steering will improve","Fuel use will fall sharply","The trailer may sway","The tow vehicle will stop faster"],"correct":2,"why":"Insufficient tongue weight can make the trailer unstable and prone to sway."},{"cat":"Towing","q":"What should you do if a trailer begins to sway?","a":["Accelerate hard","Steer sharply back and forth","Apply the tow vehicle parking brake","Ease off the accelerator, keep steering steady and avoid abrupt braking"],"correct":3,"why":"Smoothly reducing speed helps restore stability; abrupt inputs can worsen sway."},{"cat":"Towing","q":"Why is extra following distance needed when towing?","a":["The combination is heavier and takes longer to stop","The trailer makes the vehicle narrower","The engine becomes quieter","The speed limit no longer applies"],"correct":0,"why":"Added mass increases stopping distance and reduces manoeuvrability."},{"cat":"Towing","q":"What should you remember when turning with a trailer?","a":["Make the turn as sharply as possible","The trailer tracks inside the tow vehicle’s path, so turns need extra room","The trailer turns outside every curve","Turn from the shoulder"],"correct":1,"why":"Off-tracking means trailer wheels cut closer to the inside of the turn."},{"cat":"Towing","q":"Before backing a trailer, what is helpful?","a":["Accelerate quickly","Turn off warning lights","Plan the path, use mirrors and a spotter when available","Disconnect the safety chains"],"correct":2,"why":"Backing is easier and safer with a planned path, slow movement and clear communication."},{"cat":"Towing","q":"May passengers ride in a travel trailer while it is being towed?","a":["Yes if belted","Only on highways","Only adults may","No"],"correct":3,"why":"Passengers must ride in an approved seating position in the tow vehicle, not in the trailer."}];
const DEFAULT={xp:0,best:0,missed:[],seen:0,correct:0,streak:0,bestStreak:0,stats:{},bookmarks:[]};
let state;
try{state=Object.assign(DEFAULT,JSON.parse(localStorage.getItem('andyDriveState')||'{}'))}catch(e){state={...DEFAULT}}
const app=document.getElementById('app');
function save(){try{localStorage.setItem('andyDriveState',JSON.stringify(state))}catch(e){}}
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function header(){return `<div class="top"><div class="brand">Andy’s Alberta Road Quest</div><div class="pill">${state.xp} XP</div></div>`}
function masteryFor(indices){let attempts=0,correct=0;indices.forEach(i=>{const x=state.stats[i]||{};attempts+=x.attempts||0;correct+=x.correct||0});return attempts?Math.round(correct/attempts*100):0}
function home(){const cats=[...new Set(QUESTIONS.map(q=>q.cat))];const overall=state.seen?Math.round(state.correct/state.seen*100):0;app.innerHTML=`<div class="shell">${header()}<div class="card"><h1>Choose a mission</h1><p class="muted">Unlimited play. Everything works offline and progress stays on this device.</p><div class="grid"><button class="btn primary" data-mode="quick">Quick Play · 10</button><button class="btn primary" data-mode="exam">Mock Test · 30</button><button class="btn" data-mode="custom">Custom Quiz</button><button class="btn" data-mode="endless">Endless Mode</button><button class="btn" data-mode="missed">Retry all missed (${state.missed.length})</button><button class="btn" data-mode="bookmarks">Saved questions (${state.bookmarks.length})</button><button class="btn" data-mode="study">Flashcard Study</button><button class="btn" data-mode="spotter">Road Trip Spotter</button></div><div class="section"><h2>Practice a topic</h2><div class="grid">${cats.map(c=>{const ids=QUESTIONS.map((q,i)=>q.cat===c?i:-1).filter(i=>i>=0);return `<button class="btn cat" data-cat="${c}"><strong>${c}</strong><span class="topic-meta">${ids.length} questions · ${masteryFor(ids)}% mastery</span><div class="meter"><span style="width:${masteryFor(ids)}%"></span></div></button>`}).join('')}</div></div><div class="section"><h2>Progress</h2><div class="grid3"><div class="stat"><div class="big">${overall}%</div><div class="muted">Overall accuracy</div></div><div class="stat"><div class="big">${state.best}%</div><div class="muted">Best mock test</div></div><div class="stat"><div class="big">${state.bestStreak}</div><div class="muted">Best streak</div></div></div><div class="toolbar" style="margin-top:12px"><button id="details" class="btn">Detailed progress</button><button id="coverage" class="btn">Guide coverage</button><button id="reset" class="btn">Reset progress</button></div></div></div><div class="footer">Based on Alberta Driver’s Guide: Cars and Light Trucks, Spring 2026. Study practice only; not an official test.</div></div>`;
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>startMode(b.dataset.mode)));document.querySelectorAll('.cat').forEach(b=>b.addEventListener('click',()=>{const q=QUESTIONS.filter(x=>x.cat===b.dataset.cat);quiz(shuffle(q),b.dataset.cat)}));document.getElementById('details').addEventListener('click',progressPage);document.getElementById('coverage').addEventListener('click',coveragePage);document.getElementById('reset').addEventListener('click',()=>{if(confirm('Reset all XP, scores and missed questions?')){state={...DEFAULT,stats:{},missed:[],bookmarks:[]};save();home()}})}
function startMode(m){if(m==='quick')quiz(shuffle(QUESTIONS).slice(0,10),'Quick Play');if(m==='exam')quiz(shuffle(QUESTIONS).slice(0,30),'Mock Test',true);if(m==='custom')customPage();if(m==='endless')endless();if(m==='missed'){const qs=state.missed.map(i=>QUESTIONS[i]).filter(Boolean);quiz(shuffle(qs),'Missed Questions')}if(m==='bookmarks'){const qs=state.bookmarks.map(i=>QUESTIONS[i]).filter(Boolean);quiz(shuffle(qs),'Saved Questions')}if(m==='study')study();if(m==='spotter')spotter()}
function customPage(){const cats=[...new Set(QUESTIONS.map(q=>q.cat))];app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><h1>Custom Quiz</h1><button id="home" class="btn">Home</button></div><label><strong>Topic</strong><select id="topic"><option value="all">All topics</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><label style="display:block;margin-top:14px"><strong>Number of questions</strong><select id="count"><option>5</option><option selected>10</option><option>20</option><option>30</option><option>50</option><option value="all">All available</option></select></label><button id="start" class="btn primary" style="width:100%;margin-top:16px">Start quiz</button></div></div>`;document.getElementById('home').addEventListener('click',home);document.getElementById('start').addEventListener('click',()=>{const t=document.getElementById('topic').value;let pool=t==='all'?QUESTIONS:QUESTIONS.filter(q=>q.cat===t);pool=shuffle(pool);const c=document.getElementById('count').value;if(c!=='all')pool=pool.slice(0,+c);quiz(pool,t==='all'?'Custom Quiz':t)})}
function record(idx,ok){state.seen++;state.stats[idx]=state.stats[idx]||{attempts:0,correct:0};state.stats[idx].attempts++;if(ok){state.correct++;state.stats[idx].correct++;state.xp+=10;state.streak++;state.bestStreak=Math.max(state.bestStreak,state.streak);state.missed=state.missed.filter(x=>x!==idx)}else{state.xp+=2;state.streak=0;if(!state.missed.includes(idx))state.missed.push(idx)}save()}
function quiz(qs,title,isExam=false){if(!qs.length){alert('There are no questions in this set yet.');return home()}let n=0,score=0,locked=false;const ids=qs.map(q=>QUESTIONS.indexOf(q));function render(){const q=qs[n],idx=ids[n],saved=state.bookmarks.includes(idx);app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><span class="pill">${title}</span><span>${n+1} / ${qs.length}</span></div><div class="progress"><div class="bar" style="width:${(n/qs.length)*100}%"></div></div><div class="row"><h2 style="margin-bottom:8px">${q.q}</h2><button id="bookmark" class="btn tiny" aria-label="Save question">${saved?'★ Saved':'☆ Save'}</button></div><div id="answers">${q.a.map((x,i)=>`<button class="btn answer" data-i="${i}">${x}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div><button id="next" class="btn primary" style="display:none;width:100%;margin-top:12px">${n===qs.length-1?'See results':'Next question'}</button></div></div>`;locked=false;document.querySelectorAll('.answer').forEach(b=>b.addEventListener('click',()=>choose(+b.dataset.i)));document.getElementById('next').addEventListener('click',()=>{n++;n>=qs.length?finish():render()});document.getElementById('bookmark').addEventListener('click',()=>{state.bookmarks.includes(idx)?state.bookmarks=state.bookmarks.filter(x=>x!==idx):state.bookmarks.push(idx);save();render()})}
function choose(i){if(locked)return;locked=true;const q=qs[n],ok=i===q.correct;record(ids[n],ok);if(ok)score++;document.querySelectorAll('.answer').forEach((b,j)=>{if(j===q.correct)b.classList.add('correct');else if(j===i)b.classList.add('wrong');b.disabled=true});document.getElementById('feedback').innerHTML=`<div class="feedback"><strong>${ok?'Correct · +10 XP':'Not quite · +2 XP'}</strong><br>${q.why}</div>`;document.getElementById('next').style.display='block'}
function finish(){const pct=Math.round(score/qs.length*100);if(isExam&&pct>state.best){state.best=pct;save()}const rank=pct>=90?'Road Master':pct>=80?'Safe Navigator':pct>=70?'Rookie Driver':'Keep Practising';app.innerHTML=`<div class="shell">${header()}<div class="card" style="text-align:center"><div class="big">${pct}%</div><h1>${rank}</h1><p>${score} of ${qs.length} correct</p><div class="grid"><button id="again" class="btn primary">Play again</button><button id="missedNow" class="btn">Review missed</button><button id="home" class="btn">Home</button></div></div></div>`;document.getElementById('again').addEventListener('click',()=>quiz(shuffle(qs),title,isExam));document.getElementById('missedNow').addEventListener('click',()=>startMode('missed'));document.getElementById('home').addEventListener('click',home)}render()}
function endless(){let score=0,n=0;function next(){const q=QUESTIONS[Math.floor(Math.random()*QUESTIONS.length)],idx=QUESTIONS.indexOf(q);app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><span class="pill">Endless · ${score} correct</span><button id="stop" class="btn">Finish</button></div><h2 style="margin-top:18px">${q.q}</h2>${q.a.map((x,i)=>`<button class="btn answer" data-i="${i}">${x}</button>`).join('')}<div id="feedback"></div><button id="next" class="btn primary" style="display:none;width:100%;margin-top:12px">Next</button></div></div>`;let locked=false;document.getElementById('stop').addEventListener('click',home);document.querySelectorAll('.answer').forEach(b=>b.addEventListener('click',()=>{if(locked)return;locked=true;const i=+b.dataset.i,ok=i===q.correct;record(idx,ok);n++;if(ok)score++;document.querySelectorAll('.answer').forEach((x,j)=>{if(j===q.correct)x.classList.add('correct');else if(j===i)x.classList.add('wrong');x.disabled=true});document.getElementById('feedback').innerHTML=`<div class="feedback"><strong>${ok?'Correct':'Not quite'}</strong><br>${q.why}</div>`;document.getElementById('next').style.display='block'}));document.getElementById('next').addEventListener('click',next)}next()}
function study(){let deck=shuffle(QUESTIONS),n=0,shown=false;function render(){const q=deck[n];app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><span class="pill">Flashcards</span><span>${n+1} / ${deck.length}</span></div><h2 style="margin-top:20px">${q.q}</h2><div id="answer" class="feedback" style="display:${shown?'block':'none'}"><strong>${q.a[q.correct]}</strong><br>${q.why}</div><div class="grid" style="margin-top:14px"><button id="show" class="btn primary">${shown?'Hide answer':'Show answer'}</button><button id="next" class="btn">Next card</button><button id="home" class="btn">Home</button></div></div></div>`;document.getElementById('show').addEventListener('click',()=>{shown=!shown;render()});document.getElementById('next').addEventListener('click',()=>{n=(n+1)%deck.length;shown=false;render()});document.getElementById('home').addEventListener('click',home)}render()}
function progressPage(){const cats=[...new Set(QUESTIONS.map(q=>q.cat))];app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><h1>Detailed progress</h1><button id="home" class="btn">Home</button></div><div class="review-list">${cats.map(c=>{const ids=QUESTIONS.map((q,i)=>q.cat===c?i:-1).filter(i=>i>=0),m=masteryFor(ids),attempted=ids.filter(i=>(state.stats[i]?.attempts||0)>0).length;return `<div class="review-item"><div class="row"><strong>${c}</strong><span>${m}%</span></div><div class="meter"><span style="width:${m}%"></span></div><div class="topic-meta">${attempted} of ${ids.length} questions attempted</div></div>`}).join('')}</div></div></div>`;document.getElementById('home').addEventListener('click',home)}

function coveragePage(){const chapters=[
['1. Licensing Information',['Licensing']],
['2. Traffic Control',['Signals','Signs & Speed','Zones']],
['3. The Basics of Driving',['Driving Basics','Parking']],
['4. Intersections and Turns',['Intersections']],
['5. Highways and Freeways',['Highways']],
['6. Emergencies and Challenging Conditions',['Hazards']],
['7. Responsible Driving',['Responsible Driving']],
['8. Sharing the Road',['Sharing the Road']],
['9. Driving Within the Law',['Law & Fitness']],
['10. Towing a Trailer',['Towing']]
];app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><h1>Guide coverage</h1><button id="home" class="btn">Home</button></div><p class="muted">Every chapter of the Spring 2026 guide is represented. Question counts show the current bank, not a promise that every sentence in the guide appears as a separate question.</p><div class="review-list">${chapters.map(([name,cats])=>{const count=QUESTIONS.filter(q=>cats.includes(q.cat)).length;return `<div class="review-item"><div class="row"><strong>${name}</strong><span>${count} questions</span></div><div class="topic-meta">${cats.join(' · ')}</div></div>`}).join('')}</div><div class="feedback" style="margin-top:14px"><strong>${QUESTIONS.length} total questions</strong><br>Use Custom Quiz → All available for a full-bank run.</div></div></div>`;document.getElementById('home').addEventListener('click',home)}

function spotter(){const items=['Stop sign','Yield sign','School or playground sign','Construction sign','Pedestrian crossing','Merge sign','Cyclist','Large truck blind spot','Hidden driveway or blocked view','Driver following too closely','Railway crossing','Vehicle signalling a lane change','Emergency vehicle','Snowplow or road-maintenance vehicle'];app.innerHTML=`<div class="shell">${header()}<div class="card"><div class="row"><h1>Road Trip Spotter</h1><button id="home" class="btn">Home</button></div><p class="muted">Passenger activity only. Complete this mission as many times as you like.</p>${items.map((x,i)=>`<label class="spot"><input type="checkbox" data-i="${i}"><span>${x}</span></label>`).join('')}<div id="spotResult" class="feedback">0 of ${items.length} spotted</div><button id="restart" class="btn" style="width:100%;margin-top:12px">Start a new round</button></div></div>`;document.getElementById('home').addEventListener('click',home);document.getElementById('restart').addEventListener('click',spotter);let awarded=false;document.querySelectorAll('input[type=checkbox]').forEach(x=>x.addEventListener('change',()=>{const done=document.querySelectorAll('input:checked').length;document.getElementById('spotResult').textContent=`${done} of ${items.length} spotted`;if(done===items.length&&!awarded){awarded=true;state.xp+=50;save();document.getElementById('spotResult').innerHTML='<strong>Mission complete · +50 XP</strong>'}}))}
home();

if('serviceWorker' in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js');